177	export function createFrameCoalescer<T>(callback: (value: T) => void): {
178	  push: (value: T) => void;
179	  flush: () => void;
180	  cancel: () => void;
181	} {
182	  let pending: T | undefined;
183	  let scheduled = false;
184	  let frame: number | null = null;
185	
186	  const deliver = () => {
187	    scheduled = false;
188	    frame = null;
189	    if (pending === undefined) return;
190	    const value = pending;
191	    pending = undefined;
192	    callback(value);
193	  };
194	
195	  return {
196	    push(value) {
197	      pending = value;
198	      if (scheduled) return;
199	      scheduled = true;
200	      if (typeof requestAnimationFrame === "function") {
201	        frame = requestAnimationFrame(deliver);
202	      } else {
203	        queueMicrotask(deliver);
204	      }
205	    },
206	    flush() {
207	      if (frame !== null && typeof cancelAnimationFrame === "function") {
208	        cancelAnimationFrame(frame);
209	      }
210	      deliver();
211	    },
212	    cancel() {
213	      if (frame !== null && typeof cancelAnimationFrame === "function") {
214	        cancelAnimationFrame(frame);
215	      }
216	      frame = null;
217	      scheduled = false;

